using ModelContextProtocol.Server;
using System.Text.Json;

[McpServerResourceType]
public static class ConfigResources
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["version"] = "1.0.0",
        ["environment"] = "production",
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["betaFeatures"] = false
        }
    };

    [McpServerResource(Name = "app-config",
        Uri = "config://app",
        Description = "Returns the current application configuration",
        MimeType = "application/json")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(Name = "db-config",
        Uri = "config://database",
        Description = "Returns database connection settings (non-sensitive)",
        MimeType = "application/json")]
    public static string GetDatabaseConfig()
    {
        var dbConfig = new
        {
            host = "db.example.com",
            port = 5432,
            database = "appdb",
            maxPoolSize = 20,
            timeoutSeconds = 30
        };
        return JsonSerializer.Serialize(dbConfig, new JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool(Name = "echo"), Description("Echoes the input message back")]
    public static string Echo([Description("Message to echo")] string message)
    {
        return $"Echo: {message}";
    }

    [McpServerTool(Name = "get_timestamp"), Description("Returns the current UTC timestamp")]
    public static string GetTimestamp()
    {
        return DateTime.UtcNow.ToString("o");
    }
}

